  function quote(p,c){return p.type==='basin'?basinQuote(p,c):p.type==='tile'?tileQuote(p,c):p.type==='door'?doorQuote(p,c):p.type==='cube'?cubeQuote(p,c):furnQuote(p,c)}
  function defaultCfg(p,sub){
    if(p.type==='cube')return cubeDefault(p);
    if(p.type==='tile'){var tc={sc:tileSc(p)[0],mq:PR.tile.mqDefault,lot:0},l0=curLot(p,tc);if(l0)tc.mq=lotW(l0)?l0.mq:Math.min(tc.mq,Math.floor(l0.mq));return tc}
    if(p.type==='basin')return{w:bQ(p)?PR.basin.big.def:p.basin.w,d:PR.basin.depth.def,v:'quadrata',fin:PR.basin.finiture[0],ton:'',dbl:false};
    if(p.type==='door'){
      var open=sub==='scorrevoli'?'scorrevole-interno':sub==='filo-muro'?'filo-muro':'battente';
      var dc={serv:'',reg:'',open:open,size:'80',w:80,h:210,ex:{},fin:p.finishes[0],ral:p.line==='laminata'?'':'9010',hand:'dx',wall:PR.door.tech.stdWall};if(p.onlyOpen)dc.open=p.onlyOpen;stdVano(dc);return dc;
    }
    var s=p.std[0];return{size:0,w:s.w,d:s.d,h:s.h,fin:p.finishes[0],ral:p.finishes[0]==='Laccato RAL'?'9010':''};
  }
  function fromPrice(p,sub){
    if(p.type==='cube')return cubeQuote(p,cubeDefault(p)).unit;
    if(p.type==='tile')return tileFrom(p);
    if(p.type==='basin')return bQ(p)?0:basinPrice(p.basin.w);
    if(p.type==='door'){var dq=defaultCfg(p,sub);if(p.onlyOpen==='filo-muro'&&opening('filo-muro').grezza)dq.fmFin='grezza';return doorQuote(p,dq).unit}
    return Math.min.apply(null,p.std.map(function(s){return s.price}));
  }
  function cfgSummary(p,c){
    if(p.type==='basin')return basinSum(p,c);
    if(p.type==='tile'){var cl=curLot(p,c);return (cl&&cl.fmt?cl.fmt.replace('x','×'):p.tile.fmt.map(function(x){return x.replace('x','×')}).join(' / '))+' cm · '+(cl&&cl.fin?cl.fin:(p.tile.fin.join('/')||'Naturale'))+' · '+tileS(p,c.sc).label+' · '+mqF(c.mq)+' m²'+(cl?(lotW(cl)?LOTT.sw:' · '+tl(LOTT.sp,{n:mqF(cl.mq)})):'')}
    if(p.type==='cube'){var D=cubeDims(c),cnt={};(c.cells||[]).forEach(function(x){if(x!=='vuoto')cnt[x]=(cnt[x]||0)+1});
      var ins=PR.cube.inserts.filter(function(i){return cnt[i.id]}).map(function(i){return cnt[i.id]+' '+i.label.toLowerCase()});
      var b=PR.cube.bases.find(function(x){return x.id===c.base});
      return [c.cols+'×'+c.rows+' θήκες των '+c.cube+' cm',D.w+'×'+c.depth+'×'+D.h+' cm',c.fin==='Laccato RAL'?'RAL '+(c.ral||''):c.fin].concat(ins).concat(b&&b.id!=='nessuna'?[b.label]:[]).join(' · ')}
    if(p.type==='door'){
      var op=opening(c.open), ex=PR.door.extras.filter(function(x){return c.ex&&c.ex[x.id]&&extraOk(x,c)}).map(function(x){return x.label.split(' (')[0]});
      var g=doorGeom(c);return [op.label+(c.hand==='sx'?' αριστερή':' δεξιά'), c.size==='custom'?'άνοιγμα '+c.vw+'×'+c.vh+' mm, τοίχος '+c.wall+' mm (φύλλο '+g.lw+'×'+g.lh+')':c.w+'×'+PR.door.height+' cm, τοίχος '+c.wall+' mm', p.line==='laminata'?p.finishes[0]:fmGrezza(c)?'ακατέργαστη για βάψιμο':'RAL '+(c.ral||'προς επιλογή')].concat(ex).concat(service(c.serv)?[service(c.serv).label]:['χωρίς μεταφορά και τοποθέτηση']).join(' · ');
    }
    var s=c.size==='custom'?{w:c.w,d:c.d,h:c.h}:(p.std[c.size|0]||p.std[0]);
    return s.w+'×'+s.d+'×'+s.h+' cm'+(c.size==='custom'?' (κατά παραγγελία)':'')+' · '+(c.fin==='Laccato RAL'?'RAL '+(c.ral||'προς επιλογή'):c.fin);
  }

  /* ---------- numeri animati ---------- */
  function tween(el,to,fmt){
    fmt=fmt||function(v){return eur.format(v)};
    var from=parseFloat(el.dataset.v||to)||0;el.dataset.v=to;
    if(RM||from===to){el.textContent=fmt(to);return}
    var t0=performance.now(),d=520;
    (function f(t){var k=Math.min(1,(t-t0)/d),e=1-Math.pow(1-k,4);el.textContent=fmt(Math.round(from+(to-from)*e));if(k<1)requestAnimationFrame(f)})(t0);
    if(el.animate)el.animate([{transform:'translateY(-3px)',color:'#c0392b'},{transform:'none'}],{duration:500,easing:'cubic-bezier(.16,1,.3,1)'});
  }

  /* ---------- card prodotto ---------- */
  function card(p,sub){
    if(p.type==='tile')return tileCard(p);
    if(p.type==='basin')return basinCard(p);
    var fav=favs.indexOf(p.id)>=0, s=p.std&&p.std[0];
    var price=fromPrice(p,sub), many=p.type==='door'||(p.std&&p.std.length>1)||p.custom;
    var top=p.type==='door'?'<span class="s-card-line"><i></i>'+esc(p.lineLabel)+'</span>':'';
    if(p.type==='cube'){var cc=cubeDefault(p),cd=cubeDims(cc);p._thumb=svgURI(cubeSVG(cc));s={w:cd.w,d:cc.depth,h:cd.h};p.std=null}
    var dims=p.type==='cube'?'<span class="s-dim">'+s.w+' × '+s.d+' × '+s.h+' cm · '+p.preset.cols*p.preset.rows+' θήκες</span>':s?'<span class="s-dim">'+s.w+' × '+s.d+' × '+s.h+' cm'+(p.std.length>1?' · '+p.std.length+' διαστάσεις':'')+'</span>':'<span class="s-dim">Π 60–90 × Υ 210 cm · και εκτός τυποποίησης</span>';
    var sw='<span class="s-swatches">'+(p.finishes||[]).slice(0,5).map(function(f){return '<i title="'+esc(f)+'" style="background:'+swatch(f)+'"></i>'}).join('')+'</span>';
    return '<article class="s-card" data-type="'+p.type+'" data-id="'+esc(p.id)+'">'
      +'<a class="s-card-img" href="'+pURL(p)+'" tabindex="-1" aria-label="Άνοιγμα '+esc(p.name)+'"><img '+(p._thumb?'src="'+p._thumb+'"':imgAttrs(p))+' alt="'+esc(p.name)+'" loading="lazy" decoding="async"><span class="glare"></span>'
      +(p.badge?'<span class="s-badge">'+esc(p.badge)+'</span>':'')+(p.custom||p.type==='door'?'<span class="s-badge g r2">Κατά παραγγελία</span>':'')
      +'<span class="s-card-q">'+IC.eye+'Ανακαλύψτε και διαμορφώστε</span></a>'
      +top+'<h3><a href="'+pURL(p)+'">'+esc(p.name)+'</a></h3><p class="s-desc">'+esc(p.desc||'')+'</p>'+dims+sw
      +'<div class="s-price">'+(many?'<small>από</small>':'')+eur.format(price)+(p.type==='door'?'<span>+ ΦΠΑ · με τοποθέτηση σε VE/FVG '+eur.format(price+150)+'</span>':'')+'</div>'
      +'<div class="s-card-foot"><button class="s-add" type="button" data-add="'+esc(p.id)+'" aria-label="Προσθήκη '+esc(p.name)+' al carrello">'+IC.plus+'<span>Προσθήκη</span></button>'
      +'<button class="s-fav" type="button" data-fav="'+esc(p.id)+'" aria-pressed="'+fav+'" aria-label="Αποθήκευση στα αγαπημένα">'+IC.heart+'</button></div>'
      +'</article>';
  }
  function byId(id){return P.find(function(x){return x.id===id})}
  function go(u){try{sessionStorage.setItem('pdWipe','1')}catch(e){}location.href=u}
  function pURL(p){return PDI.u[p.cat+'/'+p.id]||'/shop/'+p.cat+'/'+p.id+'/'}
  function bindCards(root,sub){
    $$('[data-open]',root).forEach(function(b){if(b.tagName==='A')return;b.addEventListener('click',function(e){e.preventDefault();var p=byId(b.dataset.open);if(p)go(pURL(p))})});
    $$('[data-add]',root).forEach(function(b){b.onclick=function(){
      var p=byId(b.dataset.add);if(!p)return;
      var img=b.closest('.s-card').querySelector('.s-card-img img');
      addToCart(p,defaultCfg(p,sub),1,img);
      b.classList.add('done');b.innerHTML=IC.check+'<span>Προστέθηκε</span>';
      setTimeout(function(){b.classList.remove('done');b.innerHTML=IC.plus+'<span>Προσθήκη</span>'},1600);
    }});
    $$('[data-fav]',root).forEach(function(b){b.onclick=function(){toggleFav(b.dataset.fav,b)}});
    if(FINE&&!RM)$$('.s-card-img',root).forEach(tilt);
  }
  function toggleFav(id,b){
    var i=favs.indexOf(id);if(i>=0)favs.splice(i,1);else{favs.push(id);burst(b)}
    store('pdShopFav',favs);
    $$('[data-fav="'+id+'"]').forEach(function(x){x.setAttribute('aria-pressed',i<0);x.classList.remove('pop');void x.offsetWidth;x.classList.add('pop')});
    counts('fav');
  }
  function burst(el){
    if(RM||!el||!el.animate)return;var r=el.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2;
    for(var k=0;k<8;k++){var d=document.createElement('i');d.className='s-heart-burst';d.style.left=cx+'px';d.style.top=cy+'px';document.body.appendChild(d);
      var a=k/8*Math.PI*2;d.animate([{transform:'translate(-50%,-50%) scale(1)',opacity:1},{transform:'translate('+(Math.cos(a)*30-3)+'px,'+(Math.sin(a)*30-3)+'px) scale(.2)',opacity:0}],{duration:600,easing:'cubic-bezier(.16,1,.3,1)'}).onfinish=(function(n){return function(){n.remove()}})(d)}
  }
  function tilt(el){
    var g=el.querySelector('.glare');
    el.addEventListener('pointermove',function(e){var r=el.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;
      el.style.transform='perspective(900px) rotateX('+((.5-y)*6)+'deg) rotateY('+((x-.5)*8)+'deg)';
      if(g){g.style.setProperty('--gx',x*100+'%');g.style.setProperty('--gy',y*100+'%')}});
    el.addEventListener('pointerleave',function(){el.style.transform=''});
  }

  /* ---------- carrello ---------- */
  function counts(which){
    var n=cart.reduce(function(a,l){return a+(l.qty||1)},0);
    var cn=$('#s-cart-n'),fn=$('#s-fav-n');
    if(cn){cn.textContent=n;cn.dataset.n=n}
    if(fn){fn.textContent=favs.length;fn.dataset.n=favs.length}
    var b=which==='fav'?$('#s-fav-btn'):which==='cart'?$('#s-cart-btn'):null;
    if(b){b.classList.remove('bump');void b.offsetWidth;b.classList.add('bump')}
  }
  function addToCart(p,c,qty,fromImg,o){
    o=o||{};var q=quote(p,c), key=p.id+'|'+JSON.stringify(c)+(o.bundle?'|'+o.bundle:'');
    var ex=cart.find(function(l){return l.key===key});
    if(ex)ex.qty+=qty;else cart.push({key:key,id:p.id,type:p.type,name:p.type==='basin'&&!bQ(p)?'Νιπτήρας πορσελανάτου '+c.w+' cm':p.name,img:p.type==='cube'?svgURI(cubeSVG(c)):p.img,remote:p.imgRemote||p.imgFb||'',sum:cfgSummary(p,c),unit:q.unit,iva:(p.type==='door'||p.type==='tile'||p.type==='basin')?'escl':'incl',mq:p.type==='tile'?c.mq:0,qty:qty,bundle:o.bundle||'',bdisc:o.disc||0,bname:o.bname||''});
    store('pdShopCart2',cart);
    if(o.silent)return;
    fly(fromImg,function(){counts('cart')});
    toast(p.name+' προστέθηκε στο καλάθι');
  }
  function fly(img,done){
    var tgt=$('#s-cart-btn');
    if(RM||!img||!tgt||!document.body.animate){done();return}
    var a=img.getBoundingClientRect(),b=tgt.getBoundingClientRect();
    var f=document.createElement('div');f.className='s-fly';f.style.cssText='left:'+a.left+'px;top:'+a.top+'px;width:'+a.width+'px;height:'+a.height+'px';
    f.innerHTML='<img src="'+esc(img.tagName==='svg'?svgURI(img.outerHTML):(img.currentSrc||img.src))+'" alt="">';document.body.appendChild(f);
    var dx=b.left+b.width/2-(a.left+a.width/2),dy=b.top+b.height/2-(a.top+a.height/2);
    f.animate([{transform:'translate(0,0) scale(1)',opacity:1,borderRadius:'14px'},{transform:'translate('+dx*.55+'px,'+(dy*.55-120)+'px) scale(.45) rotate(-8deg)',opacity:1,offset:.55},{transform:'translate('+dx+'px,'+dy+'px) scale(.06) rotate(-16deg)',opacity:.4,borderRadius:'50%'}],{duration:850,easing:'cubic-bezier(.5,0,.2,1)'}).onfinish=function(){f.remove();done()};
  }
  var tT;
  function toast(msg){
    var t=$('#s-toast');if(!t){t=document.createElement('div');t.id='s-toast';t.className='s-toast';t.setAttribute('role','status');document.body.appendChild(t)}
    t.innerHTML='<i>'+IC.check+'</i><span>'+esc(msg)+'</span><button type="button">Δείτε το καλάθι</button>';
    t.querySelector('button').onclick=function(){t.classList.remove('show');openDrawer('cart')};
    requestAnimationFrame(function(){t.classList.add('show')});clearTimeout(tT);tT=setTimeout(function(){t.classList.remove('show')},3200);
  }
  function OF(){return (PR&&PR.offers)||{}}
  function nlT(){var n=store('pdNl'),t=+store('pdCodeT')||0;if(n){var x=n.t||(n.d?Date.parse(n.d):0);if(x&&(!t||x<t))t=x}return t}
  function codeLeft(){var N=OF().newsletter||{};if(!N.validDays)return Infinity;var t=nlT();return t?t+N.validDays*864e5-Date.now():N.validDays*864e5}
  function codeExpired(){var N=OF().newsletter||{};return !!(N.code&&store('pdCode')===N.code&&codeLeft()<=0)}
  function leftTxt(ms){var d=Math.floor(ms/864e5),h=Math.floor(ms%864e5/36e5);return d>0?d+' giorn'+(d>1?'i':'o')+(h?' e '+h+' or'+(h===1?'a':'e'):''):h>0?h+' or'+(h===1?'a':'e'):'λιγότερο από μία ώρα'}
