        if(K.next)nudge+='<div class="s-nudge"><b>Ακόμη '+K.next.need+' port'+(K.next.need>1?'e':'a')+'</b> και η έκπτωση στις πόρτες ανεβαίνει στο '+K.next.perc+'%.</div>';
