        $$('[data-rm]',b).forEach(function(x){x.onclick=function(){cart.splice(+x.dataset.rm,1);store('pdShopCart2',cart);counts();openDrawer('cart')}});
        $$('[data-q]',b).forEach(function(x){x.onclick=function(){var l=cart[+x.dataset.q];l.qty=clamp(l.qty+(+x.dataset.d),1,99);store('pdShopCart2',cart);counts();openDrawer('cart')}});
        var cf=$('#s-code-f',f);if(cf)cf.onsubmit=function(e){e.preventDefault();var v=$('#s-code-in',f).value.trim().toUpperCase();if(N.code&&v===N.code){if(!nlT())store('pdCodeT',Date.now());store('pdCode',v);if(codeLeft()<=0){var i0=$('#s-code-in',f);i0.value='';i0.placeholder='Ο κωδικός έληξε';return}openDrawer('cart')}else{var i=$('#s-code-in',f);i.value='';i.placeholder='Μη έγκυρος κωδικός';i.classList.add('err');setTimeout(function(){i.classList.remove('err')},900)}};
